  const response = await api.get('/discover/movie', {
    params: {
      with_genres: [...new Set(genres)].join(','),
      sort_by: 'popularity.desc',
      vote_count_gte: 100
    }
  });
  return response.data.results;
};

from json import loads, dumps
from datetime import datetime

def transform_raw_news_payload(raw_data):
    raw_payload = loads(raw_data)
    transformed = {
        "article_id": raw_payload.get("id"),
        "title": raw_payload.get("headline"),
        "source": raw_payload.get("publisher"),
        "published_date": raw_payload.get("date"),
        "summary": raw_payload.get("content", "")[:150],
        "processed_at": str(datetime.now())
    }
    return dumps(transformed, ensure_ascii=False)

async function getAIResponse(prompt: string): Promise<string> {
  const response = await fetch('/api/generate-text', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt }),
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const data = await response.json();
  return data.generatedText;
}
